"use client";

import { useEffect, useMemo, useState } from "react";
import { Field, fieldAria, selectClass } from "@/components/common/form-parts";
import { Combobox, type ComboOption } from "@/components/forms/combobox";
import { INDIAN_STATES } from "@/lib/constants";
import { useT } from "@/i18n/client";

/** Generated by scripts/build-location-data.mjs from the India Post directory. */
interface StateLocations {
  state: string;
  districts: Array<{ name: string; places: Array<[name: string, pin: string]> }>;
}

const cache = new Map<string, Promise<StateLocations | null>>();
const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

function loadState(state: string): Promise<StateLocations | null> {
  if (!cache.has(state)) {
    cache.set(
      state,
      fetch(`/data/locations/${slug(state)}.json`)
        .then((r) => (r.ok ? (r.json() as Promise<StateLocations>) : null))
        .catch(() => {
          cache.delete(state); // allow a retry when back online
          return null;
        }),
    );
  }
  return cache.get(state)!;
}

function useStateLocations(state: string) {
  const [loaded, setLoaded] = useState<{ state: string; data: StateLocations | null } | null>(null);
  useEffect(() => {
    if (!state) return;
    let live = true;
    loadState(state).then((data) => {
      if (live) setLoaded({ state, data });
    });
    return () => {
      live = false;
    };
  }, [state]);
  const current = loaded?.state === state ? loaded : null;
  return { data: current?.data ?? null, loading: Boolean(state) && !current };
}

export interface LocationPickerValues {
  state: string;
  district: string;
  city: string;
  pincode: string;
}

/**
 * State → District → City/Town, each searchable. Districts and towns come from
 * the India Post directory; anything missing can still be typed in.
 */
export function LocationPickers({
  values,
  onChange,
  errors,
  required,
}: {
  values: LocationPickerValues;
  onChange: (field: keyof LocationPickerValues, value: string) => void;
  errors: Partial<Record<keyof LocationPickerValues, string | undefined>>;
  required?: boolean;
}) {
  const t = useT();
  const { data, loading } = useStateLocations(values.state);
  const districtOptions = useMemo<ComboOption[]>(() => data?.districts.map((d) => ({ value: d.name })) ?? [], [data]);
  const placeOptions = useMemo<ComboOption[]>(() => {
    const district = data?.districts.find((d) => d.name === values.district);
    return district?.places.map(([value, pin]) => ({ value, hint: pin })) ?? [];
  }, [data, values.district]);

  return (
    <>
      <Field id="state" label="State / union territory" required={required} error={errors.state}>
        <select
          {...fieldAria("state", errors.state)}
          className={selectClass}
          autoComplete="address-level1"
          value={values.state}
          onChange={(e) => {
            onChange("state", e.target.value);
            onChange("district", "");
            onChange("city", "");
          }}
        >
          <option value="">{t("Select…")}</option>
          {INDIAN_STATES.map((s) => (
            <option key={s} value={s}>
              {t(s)}
            </option>
          ))}
        </select>
      </Field>
      <div className="grid gap-4 sm:grid-cols-2">
        <Field id="district" label="District" required={required} error={errors.district} hint={values.state ? undefined : "Choose your state first."}>
          <Combobox
            id="district"
            value={values.district}
            options={districtOptions}
            loading={loading}
            disabled={!values.state}
            placeholder={values.state ? "Search district" : "Choose a state first"}
            invalid={Boolean(errors.district)}
            describedBy={errors.district ? "district-error" : values.state ? undefined : "district-hint"}
            emptyText="Not listed? Type the name"
            onChange={(v) => {
              if (v !== values.district) onChange("city", "");
              onChange("district", v);
            }}
          />
        </Field>
        <Field id="city" label="City / town / village" required={required} error={errors.city}>
          <Combobox
            id="city"
            value={values.city}
            options={placeOptions}
            disabled={!values.district}
            placeholder={values.district ? "Search city, town or village" : "Choose a district first"}
            invalid={Boolean(errors.city)}
            describedBy={errors.city ? "city-error" : undefined}
            emptyText="Not listed? Type the name"
            onChange={(v, option) => {
              onChange("city", v);
              // Fill the PIN from the post office, without overwriting one the donor typed.
              if (option?.hint && !values.pincode) onChange("pincode", option.hint);
            }}
          />
        </Field>
      </div>
    </>
  );
}
